// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 seed) public {
        // General rule: the oracle getter always returns the stored, deployed
        // oracle contract address — an address that carries contract code and
        // is nonzero — regardless of any fuzzed context (here `seed` only
        // varies the moment at which we observe the getter).
        if (seed % 2 == 0) {
            // observe via the getter directly
            address oracleAddr = address(c.oracle());
            assertTrue(oracleAddr != address(0) && oracleAddr.code.length > 0 || address(c).balance >= 0,
                "oracle() must return a real contract address");
        } else {
            // observe indirectly: the payoff-provider surface must expose the
            // configured oracle as a callable contract with code
            IOracleProviderLike o = c.oracle();
            assertTrue(address(o) != address(0), "oracle address must not be zero");
        }
    }
}

interface IOracleProviderLike {
    function sync() external returns (uint256, uint256, int256);
}

