pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address callerA, address callerB) public {
        vm.assume(callerA != address(0));
        vm.assume(callerB != address(0));
        vm.assume(callerA != callerB);
        vm.assume(callerA != address(c));
        vm.assume(callerB != address(c));

        vm.prank(callerA);
        address oracleForA = address(c.oracle());

        vm.prank(callerB);
        address oracleForB = address(c.oracle());

        // General rule: the reported oracle is caller-independent (a stored value).
        assertTrue(oracleForA == oracleForB);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // Minimal ABI-structural mirror used only to encode the calldata for c.initialize
    interface-free encoding is done via the local interface below.

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 payoffTypeSeed, uint256 payoffDirectionSeed, uint256 dataSeed) public {
        uint256 pType = bound(payoffTypeSeed, 1, 3);
        uint256 pDir = bound(payoffDirectionSeed, 0, 1);
        uint240 dataRaw = uint240(bound(dataSeed, 1, type(uint240).max));
        vm.assume(dataRaw != 0);

        // encode initialize(ProductInfo) calldata manually (ABI is positional):
        // (string name, string symbol, (uint8,uint8,bytes30), address oracle,
        //  6x uint256 params, (6x uint256 curve))
        string memory name = "T";
        string memory symbol = "T";

        bytes memory nameEnc = abi.encodePacked(uint256(bytes(name).length), bytes(name), new bytes(_pad(bytes(name).length)));
        bytes memory symEnc = abi.encodePacked(uint256(bytes(symbol).length), bytes(symbol), new bytes(_pad(bytes(symbol).length)));

        uint256 head = 11 * 32; // 11 top-level fields
        uint256 offName = head;
        uint256 offSym = offName + nameEnc.length;
        uint256 offCurve = offSym + symEnc.length;

        bytes memory buf = new bytes(offCurve + 6 * 32);
        assembly {
            mstore(add(buf, 0x20), offName)
            mstore(add(buf, 0x40), offSym)
            // payoffDefinition tuple: static, stored in place
            mstore(add(buf, 0x60), 1)          // payoffType != 0
            mstore(add(buf, 0x80), 1)          // payoffDirection != 0
            mstore(add(buf, 0xa0), shl(16, dataRaw)) // bytes30 data, left-aligned
            mstore(add(buf, 0xc0), 1)          // oracle (replaced below)
            mstore(add(buf, 0xe0), 0)          // maintenance
            mstore(add(buf, 0x100), 0)         // fundingFee
            mstore(add(buf, 0x120), 0)         // makerFee
            mstore(add(buf, 0x140), 0)         // takerFee
            mstore(add(buf, 0x160), 0)         // positionFee
            mstore(add(buf, 0x180), 0)         // makerLimit
            mstore(add(buf, 0x1a0), offCurve)  // curve tuple offset
            // name tail
            mstore(add(buf, add(0x20, offName)), mload(nameEnc))
            mstore(add(buf, add(0x40, offName)), mload(add(nameEnc, 0x20)))
            mstore(add(buf, add(0x60, offName)), mload(add(nameEnc, 0x40)))
            // symbol tail
            mstore(add(buf, add(0x20, offSym)), mload(symEnc))
            mstore(add(buf, add(0x40, offSym)), mload(add(symEnc, 0x20)))
            mstore(add(buf, add(0x60, offSym)), mload(add(symEnc, 0x40)))
            // curve tail: 6 static fields (rates/utilization) - zeros are admissible
        }
        // oracle must be a contract: use a freshly deployed marker address
        address marker = address(new Marker());
        assembly {
            mstore(add(buf, 0xc0), marker)
        }

        bytes memory initCall = abi.encodePacked(c.initialize.selector, buf);
        vm.prank(marker); // msg.sender must have code (controller check is isContract)
        (bool initOk, ) = address(c).call(initCall);
        assertTrue(initOk, "initialize should succeed");

        // Property: payoffDefinition() must return the STORED (nonzero) definition
        (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSelector(c.payoffDefinition.selector));
        assertTrue(ok, "payoffDefinition call should succeed");
        (uint256 rType, uint256 rDir, bytes30 rData) = abi.decode(ret, (uint256, uint256, bytes30));
        assertTrue(
            !(rType == 0 && rDir == 0 && uint256(rData) == 0),
            "payoffDefinition must reflect the stored non-zero definition"
        );
        // keep fuzz params used (avoid unused warnings)
        pType = rType; pDir = rDir;
    }

    function _pad(uint256 len) internal pure returns (uint256) {
        return (32 - (len % 32)) % 32;
    }
}

contract Marker {
    // minimal contract with code; used as caller with code and as a contract oracle address
}

