// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    struct PD {
        uint8 payoffType;
        uint8 payoffDirection;
        bytes30 data;
    }

    struct Info {
        string name;
        string symbol;
        PD payoffDefinition;
        address oracle;
        uint256 maintenance;
        uint256 fundingFee;
        uint256 makerFee;
        uint256 takerFee;
        uint256 positionFee;
        uint256 makerLimit;
        uint128 minRate;
        uint128 maxRate;
        uint128 targetRate;
        uint128 targetUtilization;
    }

    function setUp() public { c = new C(); }

    function testFuzz_property(uint8 payoffType, uint8 payoffDirection, bytes30 data) public {
        // keep the fuzzed definition in a wide admissible domain
        payoffType = uint8(bound(payoffType, 0, 2));
        payoffDirection = uint8(bound(payoffDirection, 0, 2));
        vm.assume(uint256(data) != 0);

        // minimal code-bearing address to satisfy the oracle isContract check
        Dummy oracle = new Dummy();

        Info memory info;
        info.name = "P";
        info.symbol = "P";
        info.payoffDefinition = PD(payoffType, payoffDirection, data);
        info.oracle = address(oracle);
        info.maintenance = 1e18;
        info.fundingFee = 0;
        info.makerFee = 0;
        info.takerFee = 0;
        info.positionFee = 0;
        info.makerLimit = 1e30;
        info.minRate = 0;
        info.maxRate = 0;
        info.targetRate = 0;
        info.targetUtilization = 0;

        bytes4 initSel = bytes4(keccak256(
            "initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))"
        ));
        (bool initOk, ) = address(c).call(abi.encodeWithSelector(initSel, info));
        // definitions rejected by validation are not admissible inputs
        if (!initOk) return;

        // observe c's public getter payoffDefinition()
        bytes4 sel = bytes4(keccak256("payoffDefinition()"));
        (bool ok, bytes memory ret) = address(c).staticcall(abi.encodeWithSelector(sel));

        uint8 gotType;
        uint8 gotDir;
        bytes30 gotData;
        if (ok && ret.length >= 96) {
            (gotType, gotDir, gotData) = abi.decode(ret, (uint8, uint8, bytes30));
        }

        // GENERAL RULE: for any admissible stored payoff definition,
        // c.payoffDefinition() returns exactly the configured definition.
        assertTrue(
            ok && gotType == payoffType && gotDir == payoffDirection && gotData == data,
            "payoffDefinition() must return the stored definition"
        );
    }
}

