// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed, uint8 pt, uint8 pd, uint256 maint) public {
        bytes30 data = bytes30(bytes32(seed));
        // admissible domain: stored definition must carry a meaningful (nonzero) payload
        vm.assume(seed != 0);

        // Initialize c with a fuzzed payoff definition via its public initialize(ProductInfo).
        // ProductInfo (dynamic tuple) calldata, built word by word:
        // head: name offset, symbol offset, payoffDefinition (3 static words: type, direction, data),
        //       oracle, maintenance, fundingFee, makerFee, takerFee, positionFee, makerLimit,
        //       utilizationCurve (4 static words)
        // tail: two empty strings
        bytes memory cd = abi.encodePacked(
            C.initialize.selector,
            uint256(0x200),                    // offset to name (empty)
            uint256(0x240),                    // offset to symbol (empty)
            uint256(pt),                       // payoffType
            uint256(pd),                       // payoffDirection
            uint256(data),                     // bytes30 data
            uint256(uint160(address(this))),   // oracle (contract address, passes isContract)
            maint,                             // maintenance
            uint256(0),                        // fundingFee
            uint256(0),                        // makerFee
            uint256(0),                        // takerFee
            uint256(0),                        // positionFee
            uint256(0),                        // makerLimit
            int256(0),                         // minRate
            int256(0),                         // maxRate
            int256(0),                         // targetRate
            uint256(0),                        // targetUtilization
            uint256(0),                        // empty string: length
            uint256(0)                         // empty string: length
        );

        (bool okInit, ) = address(c).call(cd);
        require(okInit, "init failed");

        // General rule: the public payoffDefinition() getter reflects the definition stored at
        // initialization, i.e. its data field equals the fuzzed nonzero data for EVERY input.
        assertTrue(c.payoffDefinition().data == data);
    }
}

