pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(bytes30 data) public {
        // keep data in the admissible (nonzero) domain so a stored definition is distinguishable
        vm.assume(data != bytes30(0));

        // build an admissible payoff definition with the fuzzed data field
        PayoffDefinition memory pd = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType(uint8(1)),
            payoffDirection: PayoffDefinitionLib.PayoffDirection(uint8(1)),
            data: data
        });

        // initialize the product: msg.sender (this test contract) has code, satisfying the
        // controller isContract check; a contract address (this test) serves as the oracle
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "T",
            symbol: "T",
            payoffDefinition: pd,
            oracle: IOracleProvider(address(this)),
            maintenance: UFixed18.wrap(1e18),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(type(uint256).max),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(0)
            })
        });
        c.initialize(info);

        // read the stored definition back through the public surface
        PayoffDefinition memory stored = c.payoffDefinition();

        // general rule: the payoff definition returned by c must preserve the stored data field
        assertTrue(
            uint256(bytes32(stored.data)) == uint256(bytes32(data)),
            "payoffDefinition must return the stored definition data"
        );
    }
}

