pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint8 payoffType, uint8 payoffDirection, uint240 data) public {
        // Admissible domain: enum fields must decode as valid enum values.
        payoffType = uint8(bound(payoffType, 0, 15));
        payoffDirection = uint8(bound(payoffDirection, 0, 15));

        // Initialize C through its public surface. The test contract itself is a valid
        // contract address for the controller/oracle slots (only isContract is checked).
        // PayoffDefinition cannot be named here, so we ABI-encode initialize's calldata
        // directly: (string,string,(uint8,uint8,bytes30),address,uint256,...,(int128,int128,int128,uint128))
        bytes memory initData = abi.encodeWithSignature(
            "initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))",
            "N",
            "S",
            (payoffType, payoffDirection, bytes30(uint256(data))),
            address(this),
            uint256(1e18),
            uint256(1e17),
            uint256(0),
            uint256(0),
            uint256(0),
            uint256(0),
            (int128(1e17), int128(1e18), int128(5e17), uint128(5e17))
        );

        (bool initOk, ) = address(c).call(initData);
        // Inputs whose initialization is rejected by C are not admissible; skip them.
        if (!initOk) return;

        // General rule: the getter exposes the stored payoff definition (its data field
        // equals what was provided at initialization). The buggy version returns a
        // zero-initialized definition, breaking this whenever data != 0.
        bytes30 stored = c.payoffDefinition().data;
        assertTrue(stored == bytes30(uint256(data)), "payoffDefinition must return the stored definition");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(int256 rawPrice) public {
        // keep the price in a domain where the Linear transform cannot overflow
        vm.assume(rawPrice > type(int128).min);
        vm.assume(rawPrice < type(int128).max);

        // mock oracle returning the fuzzed raw price (ABI-compatible tuple return)
        MockOracle oracle = new MockOracle(rawPrice);
        // controller stand-in: only needs to be a contract address
        ControllerMock controller = new ControllerMock();

        // ProductInfo calldata encoding:
        // name, symbol, PayoffDefinition(Linear=1, Single=0, multiplier=2e18),
        // oracle, maintenance..makerLimit (zeros), utilizationCurve zeros
        bytes memory initCalldata = abi.encodeWithSelector(
            c.initialize.selector,
            "N", "N",
            (uint8(1), uint8(0), bytes30(uint256(2e18))),
            address(oracle),
            uint256(0), uint256(0), uint256(0), uint256(0), uint256(0), uint256(0),
            (int128(0), int128(0), int128(0), uint128(0))
        );
        vm.prank(address(controller));
        (bool initOk, ) = address(c).call(initCalldata);
        assertTrue(initOk);

        // rule: currentVersion returns the payoff-transformed price (2x the raw price)
        (, , int256 transformedPrice) = c.currentVersion();
        assertTrue(transformedPrice == rawPrice * 2e18 / 1e18 * 1e18 / 1e18 * 2);
    }
}

contract MockOracle {
    int256 private _price;
    constructor(int256 price_) { _price = price_; }
    function currentVersion() external view returns (uint256, uint256, int256) {
        return (1, block.timestamp, _price);
    }
    function atVersion(uint256) external view returns (uint256, uint256, int256) {
        return (1, block.timestamp, _price);
    }
    function sync() external returns (uint256, uint256, int256) {
        return (1, block.timestamp, _price);
    }
}

contract ControllerMock {
    // no functions needed: initialization only requires a contract address
}
